import { debug, setDebugCwd } from "../lib/logger.js";
import {
  readStdin,
  emitHookResult,
  installHookSafetyNet,
  findAideBinary,
  detectPlatform,
} from "../lib/hook-utils.js";
import {
  collectTranscriptUsage,
  recordModelUsage,
} from "../core/model-usage.js";
