export interface UsageWriteRequest {
  binary: string;
  cwd: string;
  events: ObserveBatchEvent[];
}

export type UsageWriteResult =
  | { status: "acknowledged"; recorded: number }
  | { status: "unacknowledged"; reason: "invalid-ack" | "write-error" };

/** Acknowledged batch only: older CLI fallback cannot preserve source timestamps. */
export function recordModelUsage({
  binary,
  cwd,
  events,
}: UsageWriteRequest): UsageWriteResult {
  if (!events.length) return { status: "acknowledged", recorded: 0 };
  try {
    const output = execFileSync(binary, ["observe", "record", "--stdin"], {
      cwd,
      input: events.map((e) => JSON.stringify(e)).join("\n") + "\n",
      timeout: 10000,
      stdio: ["pipe", "pipe", "pipe"],
    });
    const text = typeof output === "string" || Buffer.isBuffer(output)
      ? output.toString()
      : "";
    const ack = /^Recorded (\d+) event\(s\)(?:, skipped (\d+))?\s*$/i.exec(
      text.trim(),
    );
    if (
      ack !== null &&
      Number(ack[1]) === events.length &&
      Number(ack[2] ?? 0) === 0
    ) return { status: "acknowledged", recorded: events.length };
    return { status: "unacknowledged", reason: "invalid-ack" };
  } catch (error) {
    debug(
      "model-usage",
      `Usage batch was not acknowledged: ${error instanceof Error ? error.name : "error"}`,
    );
    return { status: "unacknowledged", reason: "write-error" };
  }
}

/** Keep repeated part broadcasts cheap; durable dedup/conflict handling is in Go. */
export function createOpenCodeUsageRecorder(
  write: (request: UsageWriteRequest) => UsageWriteResult = recordModelUsage,
): (request: { binary: string; cwd: string; part: unknown }) => void {
  const acknowledged = new Set<string>();
  return ({ binary, cwd, part }) => {
    const next = openCodeUsageEvent(part);
    if (!next) return;
    const fingerprint = JSON.stringify([cwd, next]);
    if (acknowledged.has(fingerprint)) return;
    const result = write({ binary, cwd, events: [next] });
    if (result.status !== "acknowledged") return;
    acknowledged.add(fingerprint);
    if (acknowledged.size > 1024)
      acknowledged.delete(acknowledged.values().next().value!);
  };
}
